function lang(){ return T[idiomaSeleccionado] || T.es; }

function seleccionarIdioma(idioma){
  if(!T[idioma]) return;
  idiomaSeleccionado = idioma;
  document.querySelectorAll("#languageModal .language-grid button").forEach(b=>b.classList.toggle("selected", b.dataset.lang===idioma));
  const btn=document.getElementById("languageContinueBtn");
  if(btn) btn.textContent=lang().continue;
  // Se aplica la traducción, pero NO se cierra el modal.
  aplicarIdioma(idioma);
}

function continuarIdioma(){
  localStorage.setItem("espinar_idioma", idiomaSeleccionado);
  const modal=document.getElementById("languageModal");
  if(modal){ modal.classList.remove("active"); modal.style.display="none"; }
  document.body.style.overflow="";
  window.location.hash="#inicio";
  document.getElementById("inicio")?.scrollIntoView({behavior:"smooth"});
}

function abrirSelectorIdioma(){
  const modal=document.getElementById("languageModal");
  if(!modal) return;
  modal.style.display="flex"; modal.classList.add("active");
  document.body.style.overflow="hidden";
  seleccionarIdioma(localStorage.getItem("espinar_idioma") || idiomaSeleccionado || "es");
}

function abrirMenu(){ document.querySelector(".navbar nav")?.classList.toggle("active"); }

function traducirDestino(d){
  const x=DESTINO_I18N[d===destinos.canones?"canones":d===destinos.maukallacta?"maukallacta":d===destinos.kanarmaca?"kanarmaca":d===destinos.taqrachullo?"taqrachullo":"maria"]?.[idiomaSeleccionado];
  if(!x) return {category:d.category,description:d.description,experience:d.experience,ideal:d.ideal,guide:d.guide,food:d.food,hotel:d.hotel,itinerary:d.itinerary};
  return {category:x[0],description:x[1],experience:x[2],ideal:x[3],guide:x[4],food:x[5],hotel:x[6],itinerary:d.itinerary.map((a,i)=>[a[0],x[7][i]])};
}

