let STATIC_TEXT_NODES = [];
let STATIC_READY = false;

function normText(s){
  return s.replace(/\s+/g," ").trim();
}

function rememberStaticText(){
  if(STATIC_READY) return;
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
    const n=walker.currentNode;
    if(!n.parentElement) continue;
    if(["SCRIPT","STYLE","NOSCRIPT"].includes(n.parentElement.tagName)) continue;
    if(!n.nodeValue.trim()) continue;
    STATIC_TEXT_NODES.push({node:n, key:normText(n.nodeValue)});
  }
  STATIC_READY=true;
}

function applyStaticTranslations(idioma){
  rememberStaticText();
  STATIC_TEXT_NODES.forEach(({node,key})=>{
    const translated=(STATIC_I18N[idioma]&&STATIC_I18N[idioma][key]) || STATIC_I18N.es[key];
    if(translated){
      const original=node.nodeValue;
      const lead=(original.match(/^\s*/)||[""])[0];
      const trail=(original.match(/\s*$/)||[""])[0];
      node.nodeValue=lead+translated+trail;
    }
  });

  document.querySelectorAll("input,textarea").forEach(el=>{
    if(el.placeholder){
      const k=el.getAttribute("data-i18n-placeholder") || el.placeholder;
      el.setAttribute("data-i18n-placeholder",k);
      const v=ATTR_I18N[idioma]?.[k] || ATTR_I18N.es[k];
      if(v) el.placeholder=v;
    }
  });

  document.querySelectorAll("a[title]").forEach(el=>{
    const k=el.getAttribute("data-i18n-title") || el.title;
    el.setAttribute("data-i18n-title",k);
    const v=ATTR_I18N[idioma]?.[k] || k;
    el.title=v;
  });

  document.title={
    es:"Espinar Turismo | Descubre nuestra tierra",
    en:"Espinar Tourism | Discover our land",
    pt:"Espinar Turismo | Descubra nossa terra",
    fr:"Espinar Tourisme | Découvrez notre terre",
    de:"Espinar Tourismus | Entdecken Sie unser Land"
  }[idioma];
}

